// oids is the set the longest-prefix lookup searches.
var oids = func() snmp.OIDSet {
	list := make([]snmp.OID, len(entries))
	for i, e := range entries {
		list[i] = e.OID
	}
	return snmp.NewOIDSet(list)
}()

// byKey indexes entries by [snmp.OID.WireKey] for exact lookup.
var byKey = func() map[string]Entry {
	m := make(map[string]Entry, len(entries))
	for _, e := range entries {
		m[e.OID.WireKey()] = e
	}
	return m
}()

// Lookup returns the deepest entry whose OID is a prefix of oid, which
// is the entry at oid itself when one is declared, and false when no
// configured module declares a node above oid.
func Lookup(oid snmp.OID) (Entry, bool) {
	member, ok := oids.Longest(oid)
	if !ok {
		return Entry{}, false
	}
	return byKey[member.WireKey()], true
}

// Exact returns the entry declared at oid itself, and false when none is.
func Exact(oid snmp.OID) (Entry, bool) {
	e, ok := byKey[oid.WireKey()]
	return e, ok
}

// Entries returns a copy of the table in OID order.
func Entries() []Entry {
	out := make([]Entry, len(entries))
	copy(out, entries)
	return out
}
